-- An explicit empty tags line, `tags: []`, on all-systems classes that were reviewed and
-- left untagged on purpose: plain races, and classes whose derived tags (magic,
-- psionics, mega-damage, horror-factor) already say what they are.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~054-class-tags-untagged-2.sql
--
-- A TILDE SCRIPT ON PURPOSE: seven fix- scripts rewrite a class's whole
-- markdown, and any that sorted after this file would erase the tags on a
-- rebuild. Guarded on the class having no tags line, so a re-run is a no-op.
-- The tilde number is claimed at merge.

UPDATE imported_classes SET markdown = replace(markdown, char(10) || 'category: occ' || char(10), char(10) || 'category: occ' || char(10) || 'tags: []' || char(10)), updated_at = datetime('now') WHERE class_id = 'necromancer-russian' AND instr(markdown, char(10) || 'tags:') = 0;
